import{_ as t,o,c as a,a0 as r}from"./chunks/framework.DPF_EvDs.js";const m=JSON.parse('{"title":"Notes","description":"","frontmatter":{},"headers":[],"relativePath":"Notes.md","filePath":"Notes.md"}'),n={name:"Notes.md"};function s(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h1><p><em>Canonical page, with its live parts: <a href="https://neurons-me.github.io/Cleaker/docs/en/Notes.html" target="_blank" rel="noreferrer">https://neurons-me.github.io/Cleaker/docs/en/Notes.html</a></em></p><p>The notebook of cleaker: the phrases that carry the idea, the concepts in one place, the grammar on a single page, what the code still lacks, and what to read and run next. Short on purpose; each part points to the page that develops it.</p><hr><h2 id="phrases" tabindex="-1">Phrases <a class="header-anchor" href="#phrases" aria-label="Permalink to &quot;Phrases&quot;">​</a></h2><blockquote><p><strong>Resolution before direction. Name before place.</strong><em>Resolutio ante directionem; nomen ante locum.</em> · שם קודם למקום</p></blockquote><ul><li><strong>Who am I, here.</strong> The question cleaker answers.</li><li><strong>Identity exists in relation to something else.</strong> There is no <code>.me</code> floating in the void, only <code>.me</code> in context.</li><li><strong>The singularity is .me.</strong> Everything grows out of it.</li><li><strong>Cleaker does not create identity. It mounts it.</strong></li><li><strong>The kernel learns. Cleaker does not reach inside.</strong> It calls <code>me.learn(memory)</code> once per remote resolution.</li><li><strong>.me is syntax. cleaker is protocol.</strong></li><li><strong>Change the space, change the branch. Change the seed, change the universe.</strong></li><li><strong>A host is never, by itself, a namespace.</strong></li><li><strong>Where you are is not what you are in.</strong></li><li><strong>Secrets are holes in the map, not flags in a DB.</strong></li><li><strong>Your existence is not required for reality to be valid.</strong> A system that exists without you can welcome you without needing you.</li><li><strong>If you can compute it, you cannot lose it.</strong></li></ul><hr><h2 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>In one line</th></tr></thead><tbody><tr><td><strong>namespace</strong></td><td>A public name, and a constant: its seed is the name, its identity hash anyone can compute. The axis.</td></tr><tr><td><strong>.me</strong></td><td>The kernel: expressions evaluated in your own process. Syntax, no network, no authority.</td></tr><tr><td><strong>cleaker</strong></td><td>The protocol: mounts a <code>.me</code> on a namespace and turns its expressions into <code>me://</code> addresses.</td></tr><tr><td><strong>mount</strong></td><td><code>cleaker(me, namespace)</code>: the <code>.me</code> becomes the root of a tree on that axis (<code>keys</code>, <code>wallet</code>, <code>contacts</code>, …).</td></tr><tr><td><strong>me.namespace</strong></td><td>Where a <code>.me</code> is mounted: <code>ana.cleaker.me</code>, or <code>cleaker.me</code> with no who. The root is derived from it.</td></tr><tr><td><strong>who</strong></td><td>A <code>.me</code> built with a who and a secret can <code>prove()</code>; an anonymous <code>.me</code> can only look.</td></tr><tr><td><strong>claim</strong></td><td>The key anchored for a namespace. The only thing that authorizes a write; the identity hash never does.</td></tr><tr><td><strong>audience</strong></td><td>Who can open a value: <code>∪</code>, <code>∩</code> (shares), <code>A \\ x</code> (at sealing), <code>{self}</code> = a secret scope <code>_()</code>.</td></tr><tr><td><strong>surface</strong></td><td>The page or host you are looking from. It shows a namespace and grants nothing inside it.</td></tr><tr><td><strong>transport / door</strong></td><td>How a request arrives (scheme, host, port). A door is not a smaller namespace.</td></tr><tr><td><strong>position</strong></td><td><code>namespace @ surface</code>, for example <code>cleaker.me @ neurons-me.github.io</code>.</td></tr><tr><td><strong><code>/</code> and <code>/?</code></strong></td><td><code>/</code> is the namespace without anyone looking; <code>/?</code> binds it to a self that can prove.</td></tr><tr><td><strong>remote pointer</strong></td><td><code>cleaker(&quot;me://ana.cleaker.me:read/profile&quot;)</code>: an address, resolved later.</td></tr><tr><td><strong>monad selector</strong></td><td><code>me://suign.neurons.me[monadlisa]/profile</code> changes where it executes, never what it means.</td></tr><tr><td><strong>surface identity</strong></td><td>The same claim primitive, for a server: &quot;this server is who it says it is&quot; as a verifiable claim (design).</td></tr></tbody></table><hr><h2 id="the-grammar-on-one-page" tabindex="-1">The grammar on one page <a class="header-anchor" href="#the-grammar-on-one-page" aria-label="Permalink to &quot;The grammar on one page&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>me://&lt;namespace&gt;[&lt;context&gt;]:&lt;operation&gt;/&lt;path&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;handle&gt;.&lt;root&gt;            ≡   &lt;root&gt;/@&lt;handle&gt;</span></span>
<span class="line"><span>me.&lt;path&gt;(value)           →   me://&lt;namespace&gt;:write/&lt;path&gt;</span></span>
<span class="line"><span>me(&quot;&lt;path&gt;&quot;)               →   me://&lt;namespace&gt;:read/&lt;path&gt;</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>namespace = base [ &#39;[&#39; context &#39;]&#39; ]? [ &#39;:&#39; operation ]? [ &#39;/&#39; path ]?</span></span>
<span class="line"><span>base      = label (&#39;.&#39; label)*</span></span>
<span class="line"><span>context   = kv (&#39;|&#39; kv)*          kv = key &#39;:&#39; value</span></span></code></pre></div><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cleaker.me[host:localhost|protocol:http|port:8161]:open/profile</span></span>
<span class="line"><span>  → base cleaker.me · context { host, protocol, port } · operation open · path profile</span></span></code></pre></div><p>The context in brackets is transport and execution detail: it never changes which namespace is meant.</p><hr><h2 id="function-and-component" tabindex="-1">Function and component <a class="header-anchor" href="#function-and-component" aria-label="Permalink to &quot;Function and component&quot;">​</a></h2><p>The same operation at two ends.</p><table tabindex="0"><thead><tr><th></th><th><code>cleaker(me)</code></th><th><code>&lt;Me&gt;&lt;Cleaker /&gt;&lt;/Me&gt;</code></th></tr></thead><tbody><tr><td><strong>Starts from</strong></td><td>a <code>.me</code> that already carries its identity</td><td>a namespace: a <code>.me</code> that carries only that</td></tr><tr><td><strong>Does</strong></td><td>mounts the <code>.me</code> and returns the node (<code>claim</code>, <code>signIn</code>, …)</td><td>draws the way in: QR, connect, sign in, register, recover</td></tr><tr><td><strong>Ends with</strong></td><td>a subject, mounted</td><td>a session whose kernel is mounted with <code>cleaker(me, { namespace })</code></td></tr><tr><td><strong>Needs</strong></td><td>the kernel in your hands</td><td>someone in front of the screen</td></tr></tbody></table><hr><h2 id="statuses-in-short" tabindex="-1">Statuses, in short <a class="header-anchor" href="#statuses-in-short" aria-label="Permalink to &quot;Statuses, in short&quot;">​</a></h2><p><code>cleaker.me reachable · 73 ms · public, no who</code> — the namespace, the state of its host, the time to <code>/__bootstrap</code>, and who is looking.</p><table tabindex="0"><thead><tr><th>QR</th><th>Means</th></tr></thead><tbody><tr><td><code>idle</code></td><td>nothing was checked</td></tr><tr><td><code>checking</code></td><td>loading, or pinging the host</td></tr><tr><td><code>confirmed</code></td><td>the host answered (reachable; nobody signed in)</td></tr><tr><td><code>off</code></td><td>nothing answers at this address</td></tr><tr><td><code>error</code></td><td>something answered and refused, or cleaker could not run</td></tr></tbody></table><p>Underneath: per host <code>transport</code> (up / down) and <code>triad</code> (verified / unverified / failed / skipped); per node <code>state</code> and <code>overall</code> (healthy / degraded / offline). The full page: <a href="./Statuses.html">Statuses</a>.</p><hr><h2 id="identity-as-it-works-today" tabindex="-1">Identity, as it works today <a class="header-anchor" href="#identity-as-it-works-today" aria-label="Permalink to &quot;Identity, as it works today&quot;">​</a></h2><ul><li><strong>Registering makes 12 words.</strong> The identity root comes from them; cleaker never receives the words, the root or the secret.</li><li><strong>The root is kept encrypted in the browser</strong> (a vault per namespace, opened with your secret). Browser storage is per address: <code>cleaker.me</code> and <code>www.cleaker.me</code> do not share it.</li><li><strong>Signing in is a proof</strong>, signed with a key derived from the root and checked against the key anchored in the claim.</li><li><strong>On another browser or device</strong>, there is no vault there: use Recover with the 12 words.</li></ul><hr><h2 id="where-the-code-is-behind-the-model" tabindex="-1">Where the code is behind the model <a class="header-anchor" href="#where-the-code-is-behind-the-model" aria-label="Permalink to &quot;Where the code is behind the model&quot;">​</a></h2><ul><li>A namespace without a who (inside <code>.me</code> or given to cleaker) needs <code>this.me</code> 4.4.0 and <code>cleaker</code> 4.0.1; older versions refuse it or do not read it.</li><li>There is no <code>overall</code> state for &quot;public, reachable, no who&quot;: an anonymous visit reports <code>degraded</code>.</li><li><code>profile.rootNamespace</code> / <code>profile.namespace</code> are deprecated but still written, until every reader uses <code>me.namespace</code>.</li><li><code>me.namespace</code> holds one mount for now; it becomes a collection once <code>.me</code> paths can hold a dotted segment.</li><li><code>cleaker()</code> with no arguments is the conceptual base form, not implemented.</li></ul><hr><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to &quot;Run it&quot;">​</a></h2><ul><li><a href="https://neurons-me.github.io/Cleaker/" target="_blank" rel="noreferrer">The home QR</a>: cleaker(me, &quot;cleaker.me&quot;) for real, in your browser: reachable, public, no who.</li><li><a href="https://neurons-me.github.io/Cleaker/docs/en/The-Algebra-of-Me.html" target="_blank" rel="noreferrer">Axioms, live</a>: Ax1 identity hash, Ax4 namespace @ surface, Ax5 a forgery refused.</li><li><a href="https://neurons-me.github.io/Cleaker/docs/en/Statuses.html" target="_blank" rel="noreferrer">Every QR status</a>: The real QR.me in each status, in your theme.</li><li><a href="https://neurons-me.github.io/social-graphs/" target="_blank" rel="noreferrer">Social Graphs</a>: Identity, trust and relationships in one live graph.</li><li><a href="https://neurons-me.github.io/robots/" target="_blank" rel="noreferrer">Robots That Understand Context</a>: The same object means different things by who looks and where.</li><li><a href="https://neurons-me.github.io/smart-cities/" target="_blank" rel="noreferrer">Smart Cities</a>: A city reacting as one connected graph.</li><li><a href="https://neurons-me.github.io/.wallet/paypal/split/" target="_blank" rel="noreferrer">.wallet Split</a>: Split bills with others using PayPal .me.</li><li><a href="https://neurons-me.github.io/.me/docs/Running-your-CoffeeShops.html" target="_blank" rel="noreferrer">Running your CoffeeShops</a>: Public menus, reactive pricing, private ops: one graph.</li><li><a href="https://neurons-me.github.io/.me/docs/Hemisphere-Scale.html" target="_blank" rel="noreferrer">Hemisphere Scale</a>: A million sensors; one flips; six recompute.</li><li><a href="https://neurons-me.github.io/.me/Demos/" target="_blank" rel="noreferrer">All .me demos</a>: Every live example of the kernel.</li></ul><hr><h2 id="read-next" tabindex="-1">Read next <a class="header-anchor" href="#read-next" aria-label="Permalink to &quot;Read next&quot;">​</a></h2><p><strong>Cleaker:</strong> <a href="./The-Model.html">The Model</a> · <a href="./Cleaker.html">Cleaker</a> · <a href="./Algebra-of-Me.html">The Algebra of .me</a> · <a href="./Statuses.html">Statuses</a> · <a href="./The-Flat-Universe.html">The Flat Universe</a></p><p><strong>Cleaker, in depth (TypeScript docs):</strong> <a href="https://neurons-me.github.io/Cleaker/Typescript/typedocs/Namespace-Is-Context.html" target="_blank" rel="noreferrer">Namespace Is Context</a> (a host is never, by itself, a namespace) · <a href="https://neurons-me.github.io/Cleaker/Typescript/typedocs/NRP-Namespaces.html" target="_blank" rel="noreferrer">NRP Namespaces</a> (the grammar) · <a href="https://neurons-me.github.io/Cleaker/Typescript/typedocs/Surface-Identity-Claims.html" target="_blank" rel="noreferrer">Surface Identity Claims</a> (claims for servers, design)</p><p><strong>.me:</strong> <a href="https://neurons-me.github.io/.me/docs/Seed.html" target="_blank" rel="noreferrer">Seed</a> · <a href="https://neurons-me.github.io/.me/docs/Syntax.html" target="_blank" rel="noreferrer">Syntax</a> · <a href="https://neurons-me.github.io/.me/docs/Operators.html" target="_blank" rel="noreferrer">Operators</a> · <a href="https://neurons-me.github.io/.me/docs/Audiences.html" target="_blank" rel="noreferrer">Audiences</a> · <a href="https://neurons-me.github.io/.me/docs/Algebra-of-Contexts.html" target="_blank" rel="noreferrer">Algebra of Contexts</a> · <a href="https://neurons-me.github.io/.me/docs/me-uri.html" target="_blank" rel="noreferrer">me:// URI</a></p><p><strong>Essays:</strong> <a href="https://neurons-me.github.io/encrypted-audiences/" target="_blank" rel="noreferrer">The Algebra of Encrypted Audiences</a> · <a href="https://suign.github.io/SetChemistry.html" target="_blank" rel="noreferrer">Cryptographic Set-Chemistry</a> · <a href="https://neurons-me.github.io/NRP/Namespace-Protocol-Resolution.html" target="_blank" rel="noreferrer">Namespace Protocol Resolution</a></p><p><strong>Where it runs:</strong> <a href="https://neurons-me.github.io/monad/" target="_blank" rel="noreferrer">monad</a> (the mesh) · <a href="https://neurons-me.github.io/netget/" target="_blank" rel="noreferrer">netget</a> (where a monad physically runs)</p>`,41)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
